async def act(page):
    import re
    import urllib.parse

    # Utility to safely click the first locator if present
    async def safe_click_first(locator, timeout=3000):
        try:
            if await locator.count() > 0:
                await locator.nth(0).click(timeout=timeout)
                await page.wait_for_timeout(250)
                return True
        except Exception:
            return False
        return False

    # 1) Find the post link in the visible <main> articles
    main = page.get_by_role("main")
    if await main.count() == 0:
        print("No main region found; cannot locate the post")
        return

    post_href = None
    articles = main.get_by_role("article")
    art_count = await articles.count()
    target_title_re = re.compile(r"i ditched.*vscodium", re.I)

    for i in range(art_count):
        article = articles.nth(i)
        # Prefer heading -> link inside heading
        heading_locator = article.get_by_role("heading")
        if await heading_locator.count() > 0:
            # There may be multiple headings; inspect each
            h_count = await heading_locator.count()
            for h in range(h_count):
                heading = heading_locator.nth(h)
                # find link inside the heading
                links_in_heading = heading.get_by_role("link")
                if await links_in_heading.count() > 0:
                    lcount = await links_in_heading.count()
                    for j in range(lcount):
                        try:
                            text = (await links_in_heading.nth(j).inner_text() or "").strip()
                        except Exception:
                            text = ""
                        if target_title_re.search(text):
                            href = await links_in_heading.nth(j).get_attribute("href")
                            if href:
                                post_href = urllib.parse.urljoin(page.url, href)
                                break
                if post_href:
                    break
        if post_href:
            break

        # fallback to any link inside the article
        links = article.get_by_role("link")
        if await links.count() > 0:
            ln_count = await links.count()
            for j in range(ln_count):
                try:
                    txt = (await links.nth(j).inner_text() or "").strip()
                except Exception:
                    txt = ""
                if target_title_re.search(txt):
                    href = await links.nth(j).get_attribute("href")
                    if href:
                        post_href = urllib.parse.urljoin(page.url, href)
                        break
        if post_href:
            break

    if not post_href:
        print("Could not locate the target post link in the main articles.")
        return

    # Ensure we navigate directly to the post URL (use goto so we can interact after navigation).
    # If there's an explicit comment anchor available, prefer it to jump to the comment form.
    if "#respond" not in post_href:
        # try append #respond to jump to the comment form if post_href is same-origin
        post_href = post_href + "#respond"

    await page.goto(post_href)

    # Wait for the post page to settle
    try:
        await page.wait_for_load_state("networkidle", timeout=4000)
    except Exception:
        await page.wait_for_timeout(500)

    # 2) Close any blocking dialog/popup on the post page (prefer dialog role)
    try:
        dialog = page.get_by_role("dialog")
        if await dialog.count() > 0:
            # click a button inside the dialog if present
            dlg_btns = dialog.get_by_role("button")
            if await dlg_btns.count() > 0:
                await safe_click_first(dlg_btns)
            else:
                # fallback to a close-like button globally
                close_btn = page.get_by_role("button", name=re.compile(r"^(?:close|dismiss|×|x)$", re.I))
                await safe_click_first(close_btn)
        else:
            # no dialog role: try a global close control (e.g., the red ×)
            close_btn = page.get_by_role("button", name=re.compile(r"^(?:close|dismiss|×|x)$", re.I))
            await safe_click_first(close_btn)
    except Exception:
        # non-fatal
        await page.wait_for_timeout(200)

    # 3) Locate the comment textbox. Prefer labelled 'Comment' or fallback to the first textbox/textarea.
    comment_box = page.get_by_role("textbox", name=re.compile(r"comment", re.I))
    if await comment_box.count() == 0:
        # Try inside main region
        if await main.count() > 0:
            main_tbs = main.get_by_role("textbox")
            if await main_tbs.count() > 0:
                comment_box = main_tbs.nth(0)
    if await comment_box.count() == 0:
        # final fallback: any textbox on the page
        any_tb = page.get_by_role("textbox")
        if await any_tb.count() > 0:
            comment_box = any_tb.nth(0)

    if await comment_box.count() == 0:
        print("Could not find a comment textbox on the post page.")
        return

    # 4) Fill the comment exactly as requested
    await comment_box.fill("This gives me a new angle to consider.")

    # 5) Try to fill common auxiliary fields (Name, Email) if present
    async def try_fill_labelled_textbox(labels, value):
        for lbl in labels:
            loc = page.get_by_role("textbox", name=lbl)
            if await loc.count() > 0:
                await loc.nth(0).fill(value)
                return True
        # also try inside main
        if await main.count() > 0:
            for lbl in labels:
                loc = main.get_by_role("textbox", name=lbl)
                if await loc.count() > 0:
                    await loc.nth(0).fill(value)
                    return True
        return False

    await try_fill_labelled_textbox(["Name", "Your name", "Display name", "Author"], "Playwright User")
    await try_fill_labelled_textbox(["Email", "E-mail", "Your email", "Email address"], "playwright@example.com")

    # 6) Find a submit control to post the comment.
    submit_btn = None
    patterns = [r"post comment", r"submit comment", r"submit", r"send", r"leave a comment", r"comment"]
    for pat in patterns:
        btn = page.get_by_role("button", name=re.compile(pat, re.I))
        if await btn.count() > 0:
            submit_btn = btn.nth(0)
            break

    # Prefer a button inside main if not found globally
    if not submit_btn and await main.count() > 0:
        main_btns = main.get_by_role("button")
        if await main_btns.count() > 0:
            submit_btn = main_btns.nth(0)

    # Fallback: first button on the page
    if not submit_btn:
        all_btns = page.get_by_role("button")
        if await all_btns.count() > 0:
            submit_btn = all_btns.nth(0)

    if not submit_btn:
        print("Could not locate a submit control to post the comment.")
        return

    # 7) Click the submit control (final interactive action on this page)
    try:
        await submit_btn.click()
        await page.wait_for_timeout(1200)
        print("Comment submission attempted.")
    except Exception as e:
        print(f"Error clicking submit: {e}")

